const item = $input.first().json;
const body = item.body ?? item;
return [{ json: { ...body, _tool: "get_compensation", _start_at: Date.now() } }];

const id = $('Get Identity').first().json;
const body = $('Normalize Input').first().json;
const target = body.employee_name_or_code || body.target || '';
return [{ json: {
  ...id,
  target_raw: target,
  requester_id: id.employee_id
}}];

const r = $input.first().json;
if (!r.id) return [{ json: { error: 'NOT_FOUND: Employee not found.' } }];
const id = $('Get Identity').first().json;
return [{ json: {
  requester_id: id.employee_id,
  target_id:    r.id,
  emp_name:     r.full_name,
  emp_code:     r.employee_code
}}];

const r = $input.first().json;
const out = {
  employee_name:  r.employee_name,
  employee_code:  r.employee_code,
  base_salary:    r.base_salary,
  currency:       r.currency
};
return [{ json: {
  ...out,
  _out: out,
  _tool_name: 'get_compensation',
  _in: { target: $('Normalize Input').first().json.employee_name_or_code || '' },
  _status: 'success',
  _error: null
}}];

const d = $input.first().json;
const id = $('Get Identity').first().json;
const start = $('Normalize Input').first().json._start_at;
const esc = s => s == null ? null : String(s).replace(/'/g, "''");
return [{ json: {
  ...d._out,
  _lws:  id.workspace_id,
  _lemp: id.employee_id ?? null,
  _ltool: d._tool_name,
  _lin:  esc(JSON.stringify(d._in  ?? {})),
  _lout: d._out != null ? esc(JSON.stringify(d._out)) : null,
  _lst:  d._status,
  _lerr: esc(d._error) ?? null,
  _llat: Date.now() - start
}}];

// Log Tool Call replaces item data with RETURNING id; go back to Prepare Log for the output
const d = $('Prepare Log').first().json;
const clean = Object.fromEntries(Object.entries(d).filter(([k]) => !k.startsWith('_l')));
return [{ json: clean }];

const item = $input.first();
// Postgres continueErrorOutput → item.json.message; Code node throw → item.json.error (string)
const rawErr = item.json?.error;
const msg = (item.json?.message
         || (typeof rawErr === 'string' ? rawErr : rawErr?.description)
         || 'Tool error').replace(/\s*\[line \d+\]$/, '');
// Map well-known CODE: prefixes; for unknown codes strip the prefix and pass the rest through
let status = 'error';
let friendly = msg;
const m = msg.match(/^([A-Z_]+):\s*(.*)/s);
const code = m?.[1];
const rest = m?.[2] || msg;
const codeMap = {
  ACCESS_DENIED:        ['denied', 'You do not have permission to perform this action.'],
  INSUFFICIENT_BALANCE: ['error',  'Insufficient PTO balance for this request.'],
  NOT_FOUND:            ['error',  'The requested resource was not found.'],
  ALREADY_DECIDED:      ['error',  'This request has already been decided.'],
  INVALID_LINK:         ['error',  'This approval link is invalid or has expired.'],
};
if (code && codeMap[code]) {
  [status, friendly] = codeMap[code];
} else if (code) {
  // Unknown CODE: prefix — use the human-readable part after the colon
  friendly = rest;
}
const id = $('Get Identity').first().json;
const start = $('Normalize Input').first().json._start_at;
const esc = s => s == null ? null : String(s).replace(/'/g, "''");
return [{ json: {
  error: friendly,
  _lws:   id.workspace_id,
  _lemp:  id.employee_id ?? null,
  _ltool: $('Normalize Input').first().json._tool,
  _lin:   esc(JSON.stringify({})),
  _lout:  null,
  _lst:   status,
  _lerr:  esc(friendly),
  _llat:  Date.now() - start
}}];

